    private void UseUserClient(string authMode, string requiredPermission)
    {
        switch (authMode)
        {
            case "anonymous":
                UseAnonymousClient();
                break;
            case "low-privilege":
                UseLowPrivilegeClient(requiredPermission);
                break;
            case "privileged":
                UsePrivilegedClient(requiredPermission);
