import React, { useState } from 'react'
import { Link } from 'react-router-dom'
import { Mail, Loader2, CheckCircle2, ArrowLeft } from 'lucide-react'
import { api } from '../lib/api-client'
import { useToast } from '../components/ui/toast'

export default function ResendConfirmation() {
  const toast = useToast()
  const [email, setEmail] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle')
  const [touched, setTouched] = useState(false)

  const isEmailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!isEmailValid) {
      toast.error('Please enter a valid email address.')
      return
    }

    setIsLoading(true)
    setStatus('idle')

    try {
      const result = await api.post('api/v1/account/resend-confirmation-email', {
        email,
      })

      if (result.isSuccessful) {
        setStatus('success')
        toast.success(result.messages?.[0] || 'Verification email sent successfully! Please check your inbox.')
      } else {
        setStatus('error')
        toast.error(result.messages?.[0] || 'Failed to resend verification email.')
      }
    } catch (err) {
      console.error(err)
      setStatus('error')
      toast.error('Failed to connect to the server. Please verify the backend is running.')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div
      className="relative min-h-screen flex items-center justify-center bg-cover bg-center bg-no-repeat px-4 py-8"
      style={{ backgroundImage: "url('/assets/img/login/login-bg.png')" }}
    >
