    [Fact]
    public async Task GetUserRolesAsync_WhenUserNotFound_ReturnsFail()
    {
        _userManager.Setup(m => m.FindByIdAsync("5")).ReturnsAsync((ApplicationUser?)null);

        var result = await _sut.GetUserRolesAsync(5);

